node -e "
const db = require('better-sqlite3')('/workspace/world.db');

// 1. Update CI-0006 quantity from 3 to 2
db.prepare(\"UPDATE cart_items SET quantity = 2 WHERE cart_item_id = 'CI-0006'\").run();

// 2. Remove CI-0005 (Harbor Cotton Crew Tee, out of stock)
db.prepare(\"DELETE FROM cart_items WHERE cart_item_id = 'CI-0005'\").run();

// 3. Recalculate subtotal: CI-0006 (2 × \$89 = \$178) + CI-0007 (2 × \$72 = \$144) = \$322
const newSubtotal = (2 * 89) + (2 * 72);  // 322
const newItemIds = JSON.stringify(['CI-0006', 'CI-0007']);

// 4. Update cart totals and item list (keeping current shipping: standard, free)
db.prepare(\"UPDATE carts SET subtotal = ?, item_ids_json = ?, total = subtotal + shipping_cost - discount_amount - loyalty_discount + gift_wrap_fee WHERE cart_id = 'CART-user_58b0a2d6'\").run(newSubtotal, newItemIds);

// Verify
console.log('=== Updated cart ===');
console.log(db.prepare(\"SELECT * FROM carts WHERE cart_id = 'CART-user_58b0a2d6'\").get());
console.log('\n=== Remaining cart items ===');
console.log(db.prepare(\"SELECT ci.*, p.name, p.price, p.in_stock FROM cart_items ci JOIN products p ON ci.product_id = p.product_id WHERE ci.cart_id = 'CART-user_58b0a2d6'\").all());
"

